+    expect(zeroTabIndex[0].getAttribute('aria-label')).toBe('Reihe A, Platz 1, frei');
+    freeCells
+      .filter(cell => cell !== zeroTabIndex[0])
+      .forEach(cell => expect(cell.tabIndex).toBe(-1));
+  });
