61	+
62	+namespace seed_a_backend.Api.Application;
63	+
64	+/// <summary>
65	+/// Grid-Struktur kommt 1:1 aus Domain/Room (AD-8); Zellstatus wird aus BookingPosition
66	+/// abgeleitet (AD-1/AD-2) — ein Sitzplatz gilt als belegt, wenn eine nicht stornierte
67	+/// BookingPosition-Zeile (CancelledAtUtc IS NULL) mit passendem RowLabel/ColumnNumber
68	+/// existiert, unabhängig davon, ob sie aus dem Anfangsdatenbestand oder einer Buchung stammt.
69	+/// </summary>
70	+public class SeatMapService(AppDbContext db)
71	+{
72	+    public async Task<SeatMap?> GetSeatMapAsync(int eventId, CancellationToken ct = default)
73	+    {
74	+        var room = await (
75	+            from e in db.Events
76	+            join r in db.Rooms on e.RoomId equals r.Id
77	+            where e.Id == eventId
78	+            select r
79	+        ).SingleOrDefaultAsync(ct);
80	+
81	+        if (room is null)
82	+        {
83	+            return null;
84	+        }
85	+
86	+        var occupiedRows = await db.BookingPositions
87	+            .Where(bp => bp.EventId == eventId && bp.CancelledAtUtc == null)
88	+            .Select(bp => new { bp.RowLabel, bp.ColumnNumber })
89	+            .ToListAsync(ct);
90	+        var occupied = occupiedRows.Select(o => (o.RowLabel, o.ColumnNumber)).ToHashSet();
91	+
92	+        var rows = room.RowLabels
93	+            .Select(rowLabel => new SeatMapRow(
94	+                rowLabel,
95	+                Enumerable.Range(1, room.ColumnCount)
96	+                    .Select(column => new SeatMapCell(column, Status(room, occupied, rowLabel, column)))
97	+                    .ToList()))
98	+            .ToList();
99	+
100	+        return new SeatMap(room.RowLabels, room.ColumnCount, room.AisleColumns.ToList(), rows);
101	+    }
102	+
103	+    private static string Status(Room room, HashSet<(string RowLabel, int ColumnNumber)> occupied, string rowLabel, int column) =>
104	+        room.AisleColumns.Contains(column) ? "aisle"
105	+            : occupied.Contains((rowLabel, column)) ? "occupied"
106	+            : "free";
107	+}
