658	+import { Component, inject, signal } from '@angular/core';
659	+import { ActivatedRoute } from '@angular/router';
660	+import { HttpErrorResponse } from '@angular/common/http';
661	+
662	+import { EventsApiService } from '../../core/api/events-api.service';
663	+import { SeatMap } from '../../core/api/seat-map';
664	+import { SeatMapGrid } from './seat-map/seat-map';
665	+
666	+@Component({
667	+  selector: 'app-booking',
668	+  imports: [SeatMapGrid],
669	+  templateUrl: './booking.html',
670	+  styleUrl: './booking.scss'
671	+})
672	+export class BookingPage {
673	+  private readonly route = inject(ActivatedRoute);
674	+  private readonly eventsApi = inject(EventsApiService);
675	+
676	+  readonly seatMap = signal<SeatMap | null>(null);
677	+  readonly loading = signal(true);
678	+  readonly notFound = signal(false);
679	+  readonly loadError = signal(false);
680	+
681	+  constructor() {
682	+    const id = Number(this.route.snapshot.paramMap.get('id'));
683	+    if (!Number.isInteger(id) || id > 2147483647) {
684	+      this.loading.set(false);
685	+      this.notFound.set(true);
686	+      return;
687	+    }
688	+
689	+    this.eventsApi.getSeatMap(id).subscribe({
690	+      next: seatMap => {
691	+        this.seatMap.set(seatMap);
692	+        this.loading.set(false);
693	+      },
694	+      error: (err: HttpErrorResponse) => {
695	+        this.loading.set(false);
696	+        if (err.error?.code === 'EVENT_NOT_FOUND') {
697	+          this.notFound.set(true);
698	+        } else {
699	+          this.loadError.set(true);
700	+        }
701	+      }
702	+    });
703	+  }
704	+}
