990	+import { Component, ElementRef, computed, effect, input, signal, viewChild } from '@angular/core';
991	+
992	+import { SeatMap, SeatMapCell } from '../../../core/api/seat-map';
993	+
994	+interface FocusTarget {
995	+  rowIndex: number;
996	+  columnIndex: number;
997	+}
998	+
999	+const KEY_DELTAS: Record<string, { rowDelta: number; columnDelta: number }> = {
1000	+  ArrowUp: { rowDelta: -1, columnDelta: 0 },
1001	+  ArrowDown: { rowDelta: 1, columnDelta: 0 },
1002	+  ArrowLeft: { rowDelta: 0, columnDelta: -1 },
1003	+  ArrowRight: { rowDelta: 0, columnDelta: 1 }
1004	+};
1005	+
1006	+@Component({
1007	+  selector: 'app-seat-map',
1008	+  imports: [],
1009	+  templateUrl: './seat-map.html',
1010	+  styleUrl: './seat-map.scss'
1011	+})
1012	+export class SeatMapGrid {
1013	+  readonly seatMap = input.required<SeatMap>();
1014	+
1015	+  private readonly root = viewChild.required<ElementRef<HTMLElement>>('root');
1016	+
1017	+  private readonly focusTarget = signal<FocusTarget | null>(null);
1018	+
1019	+  private readonly firstFreeTarget = computed<FocusTarget | null>(() => {
1020	+    const rows = this.seatMap().rows;
1021	+    for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
1022	+      const columnIndex = rows[rowIndex].cells.findIndex(cell => cell.status === 'free');
1023	+      if (columnIndex !== -1) {
1024	+        return { rowIndex, columnIndex };
1025	+      }
1026	+    }
1027	+    return null;
1028	+  });
1029	+
1030	+  constructor() {
1031	+    effect(() => {
1032	+      const target = this.focusTarget();
1033	+      if (target === null) {
1034	+        return;
1035	+      }
1036	+      const selector = `[data-row-index="${target.rowIndex}"][data-column-index="${target.columnIndex}"]`;
1037	+      this.root().nativeElement.querySelector<HTMLButtonElement>(selector)?.focus();
1038	+    });
1039	+  }
1040	+
1041	+  isRovingTabTarget(rowIndex: number, columnIndex: number): boolean {
1042	+    const current = this.focusTarget() ?? this.firstFreeTarget();
1043	+    return current !== null && current.rowIndex === rowIndex && current.columnIndex === columnIndex;
1044	+  }
1045	+
1046	+  ariaLabel(rowLabel: string, cell: SeatMapCell): string {
1047	+    const statusText = cell.status === 'occupied' ? 'belegt' : 'frei';
1048	+    return `Reihe ${rowLabel}, Platz ${cell.columnNumber}, ${statusText}`;
1049	+  }
1050	+
1051	+  onFocus(rowIndex: number, columnIndex: number): void {
1052	+    this.focusTarget.set({ rowIndex, columnIndex });
1053	+  }
1054	+
1055	+  onKeydown(event: KeyboardEvent, rowIndex: number, columnIndex: number): void {
1056	+    const delta = KEY_DELTAS[event.key];
1057	+    if (!delta) {
1058	+      return;
1059	+    }
1060	+    event.preventDefault();
1061	+    const next = this.findNextFocusable(rowIndex, columnIndex, delta.rowDelta, delta.columnDelta);
1062	+    if (next) {
1063	+      this.focusTarget.set(next);
1064	+    }
1065	+  }
1066	+
1067	+  private findNextFocusable(rowIndex: number, columnIndex: number, rowDelta: number, columnDelta: number): FocusTarget | null {
1068	+    const rows = this.seatMap().rows;
1069	+    let r = rowIndex + rowDelta;
1070	+    let c = columnIndex + columnDelta;
1071	+    while (r >= 0 && r < rows.length && c >= 0 && c < rows[r].cells.length) {
1072	+      if (rows[r].cells[c].status === 'free') {
1073	+        return { rowIndex: r, columnIndex: c };
1074	+      }
1075	+      r += rowDelta;
1076	+      c += columnDelta;
1077	+    }
1078	+    return null;
1079	+  }
1080	+}
