72	+
73	+            var rows = room.RowLabels
74	+                .Select(rowLabel => new SeatMapRow(
75	+                    rowLabel,
76	+                    Enumerable.Range(1, room.ColumnCount)
77	+                        .Select(column => new SeatMapCell(column, Status(room, occupied, rowLabel, column)))
78	+                        .ToList()))
79	+                .ToList();
80	+
