1709	+
1710	+const KEY_DELTAS: Record<string, { rowDelta: number; columnDelta: number }> = {
1711	+  ArrowUp: { rowDelta: -1, columnDelta: 0 },
1712	+  ArrowDown: { rowDelta: 1, columnDelta: 0 },
