1723	+export class SeatMapGrid {
1724	+  readonly seatMap = input.required<SeatMap>();
1725	+
1726	+  private readonly root = viewChild.required<ElementRef<HTMLElement>>('root');
1727	+
1728	+  private readonly focusTarget = signal<FocusTarget | null>(null);
1729	+
1730	+  private readonly firstFreeTarget = computed<FocusTarget | null>(() => {
1731	+    const rows = this.seatMap().rows;
1732	+    for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
1733	+      const columnIndex = rows[rowIndex].cells.findIndex(cell => cell.status === 'free');
1734	+      if (columnIndex !== -1) {
1735	+        return { rowIndex, columnIndex };
1736	+      }
1737	+    }
1738	+    return null;
1739	+  });
1740	+
1741	+  constructor() {
1742	+    effect(() => {
1743	+      const target = this.focusTarget();
1744	+      if (target === null) {
1745	+        return;
1746	+      }
1747	+      const selector = `[data-row-index="${target.rowIndex}"][data-column-index="${target.columnIndex}"]`;
1748	+      this.root().nativeElement.querySelector<HTMLButtonElement>(selector)?.focus();
1749	+    });
1750	+  }
1751	+
1752	+  isRovingTabTarget(rowIndex: number, columnIndex: number): boolean {
1753	+    const current = this.focusTarget() ?? this.firstFreeTarget();
1754	+    return current !== null && current.rowIndex === rowIndex && current.columnIndex === columnIndex;
1755	+  }
1756	+
1757	+  ariaLabel(rowLabel: string, cell: SeatMapCell): string {
1758	+    const statusText = cell.status === 'occupied' ? 'belegt' : 'frei';
1759	+    return `Reihe ${rowLabel}, Platz ${cell.columnNumber}, ${statusText}`;
1760	+  }
1761	+
1762	+  onFocus(rowIndex: number, columnIndex: number): void {
1763	+    this.focusTarget.set({ rowIndex, columnIndex });
1764	+  }
1765	+
1766	+  onKeydown(event: KeyboardEvent, rowIndex: number, columnIndex: number): void {
1767	+    const delta = KEY_DELTAS[event.key];
1768	+    if (!delta) {
1769	+      return;
1770	+    }
1771	+    event.preventDefault();
1772	+    const next = this.findNextFocusable(rowIndex, columnIndex, delta.rowDelta, delta.columnDelta);
1773	+    if (next) {
1774	+      this.focusTarget.set(next);
1775	+    }
1776	+  }
1777	+
1778	+  private findNextFocusable(rowIndex: number, columnIndex: number, rowDelta: number, columnDelta: number): FocusTarget | null {
1779	+    const rows = this.seatMap().rows;
1780	+    let r = rowIndex + rowDelta;
1781	+    let c = columnIndex + columnDelta;
1782	+    while (r >= 0 && r < rows.length && c >= 0 && c < rows[r].cells.length) {
