5	namespace seed_a_backend.Api.Application;
6	
7	/// <summary>
8	/// Grid-Struktur kommt 1:1 aus Domain/Room (AD-8); Zellstatus wird aus BookingPosition
9	/// abgeleitet (AD-1/AD-2) — ein Sitzplatz gilt als belegt, wenn eine nicht stornierte
10	/// BookingPosition-Zeile (CancelledAtUtc IS NULL) mit passendem RowLabel/ColumnNumber
11	/// existiert, unabhängig davon, ob sie aus dem Anfangsdatenbestand oder einer Buchung stammt.
12	/// </summary>
13	public class SeatMapService(AppDbContext db)
14	{
15	    public async Task<SeatMap?> GetSeatMapAsync(int eventId, CancellationToken ct = default)
16	    {
17	        var room = await (
18	            from e in db.Events
19	            join r in db.Rooms on e.RoomId equals r.Id
20	            where e.Id == eventId
21	            select r
22	        ).SingleOrDefaultAsync(ct);
23	
24	        if (room is null)
25	        {
26	            return null;
27	        }
28	
29	        var occupiedRows = await db.BookingPositions
30	            .Where(bp => bp.EventId == eventId && bp.CancelledAtUtc == null)
31	            .Select(bp => new { bp.RowLabel, bp.ColumnNumber })
32	            .ToListAsync(ct);
33	        var occupied = occupiedRows.Select(o => (o.RowLabel, o.ColumnNumber)).ToHashSet();
34	
35	        var rows = room.RowLabels
36	            .Select(rowLabel => new SeatMapRow(
37	                rowLabel,
38	                Enumerable.Range(1, room.ColumnCount)
39	                    .Select(column => new SeatMapCell(column, Status(room, occupied, rowLabel, column)))
40	                    .ToList()))
41	            .ToList();
42	
43	        return new SeatMap(room.RowLabels, room.ColumnCount, room.AisleColumns.ToList(), rows);
44	    }
45	
46	    private static string Status(Room room, HashSet<(string RowLabel, int ColumnNumber)> occupied, string rowLabel, int column) =>
47	        room.AisleColumns.Contains(column) ? "aisle"
48	            : occupied.Contains((rowLabel, column)) ? "occupied"
49	            : "free";
50	}
